/**
 * One function per HTTP command in the registry (paths from
 * crates/ledgers-commands/src/registry.rs). Hand-written for now; these will be
 * generated by harness `client-ts` from the OpenAPI document later.
 */
import { request, type ClientConfig } from './client';
import type {
  AccountBalanceByDimensionOutput,
  AccountsListOutput,
  BalanceSheetOutput,
  BillsMatchOutput,
  EntriesListOutput,
  EntryRecord,
  KeysCreateInput,
  KeysCreateOutput,
  KeysListOutput,
  KeysRevokeOutput,
  PostEntryInput,
  PostEntryOutput,
  ProfitAndLossOutput,
  ReverseEntryInput,
  TrialBalanceOutput,
} from './types';

export type Config = ClientConfig;

/** POST /v1/entries (entries.post). Idempotent on `entry.external_id`. */
export function entriesPost(config: Config, input: PostEntryInput): Promise<PostEntryOutput> {
  return request<PostEntryOutput>(config, { method: 'POST', path: '/v1/entries', body: input });
}

/** POST /v1/entries/{external_id}/reverse (entries.reverse). Posts a reversal; never edits the original. */
export function entriesReverse(
  config: Config,
  externalId: string,
  input: ReverseEntryInput,
): Promise<PostEntryOutput> {
  return request<PostEntryOutput>(config, {
    method: 'POST',
    path: `/v1/entries/${encodeURIComponent(externalId)}/reverse`,
    body: input,
  });
}

/** GET /v1/entries (entries.list). */
export function entriesList(config: Config): Promise<EntriesListOutput> {
  return request<EntriesListOutput>(config, { method: 'GET', path: '/v1/entries' });
}

/** GET /v1/entries/{external_id} (entries.get, being added server-side in parallel). */
export function entriesGet(config: Config, externalId: string): Promise<EntryRecord> {
  return request<EntryRecord>(config, {
    method: 'GET',
    path: `/v1/entries/${encodeURIComponent(externalId)}`,
  });
}

/** GET /v1/accounts (accounts.list, being added server-side in parallel). */
export function accountsList(config: Config): Promise<AccountsListOutput> {
  return request<AccountsListOutput>(config, { method: 'GET', path: '/v1/accounts' });
}

/** GET /v1/reports/trial-balance?period=YYYY-MM (reports.trial_balance). */
export function reportsTrialBalance(config: Config, period: string): Promise<TrialBalanceOutput> {
  return request<TrialBalanceOutput>(config, {
    method: 'GET',
    path: '/v1/reports/trial-balance',
    query: { period },
  });
}

/** GET /v1/reports/p-and-l?period=YYYY-MM (reports.profit_and_loss). */
export function reportsProfitAndLoss(config: Config, period: string): Promise<ProfitAndLossOutput> {
  return request<ProfitAndLossOutput>(config, {
    method: 'GET',
    path: '/v1/reports/p-and-l',
    query: { period },
  });
}

/** GET /v1/reports/balance-sheet?as_of=YYYY-MM-DD (reports.balance_sheet). */
export function reportsBalanceSheet(config: Config, asOf: string): Promise<BalanceSheetOutput> {
  return request<BalanceSheetOutput>(config, {
    method: 'GET',
    path: '/v1/reports/balance-sheet',
    query: { as_of: asOf },
  });
}

/** GET /v1/reports/account-balance-by-dimension (reports.account_balance_by_dimension). */
export function reportsAccountBalanceByDimension(
  config: Config,
  params: { account: string; dimension: string; period: string },
): Promise<AccountBalanceByDimensionOutput> {
  return request<AccountBalanceByDimensionOutput>(config, {
    method: 'GET',
    path: '/v1/reports/account-balance-by-dimension',
    query: { account: params.account, dimension: params.dimension, period: params.period },
  });
}

/**
 * POST /v1/bills/{id}/match (bills.match). Not in the registry yet, so the
 * response is returned as the server sends it.
 */
export function billsMatch(config: Config, billId: string): Promise<BillsMatchOutput> {
  return request<BillsMatchOutput>(config, {
    method: 'POST',
    path: `/v1/bills/${encodeURIComponent(billId)}/match`,
    body: {},
  });
}

/**
 * GET /v1/keys (keys.list). Person sessions only: an agent key gets 403. The
 * list carries public prefixes; no secret is ever returned here.
 */
export function keysList(config: Config): Promise<KeysListOutput> {
  return request<KeysListOutput>(config, { method: 'GET', path: '/v1/keys' });
}

/** POST /v1/keys (keys.create). The answer carries the full token once. */
export function keysCreate(config: Config, input: KeysCreateInput): Promise<KeysCreateOutput> {
  return request<KeysCreateOutput>(config, { method: 'POST', path: '/v1/keys', body: input });
}

/** POST /v1/keys/{id}/revoke (keys.revoke). Takes effect on the next request with that key. */
export function keysRevoke(config: Config, id: string): Promise<KeysRevokeOutput> {
  return request<KeysRevokeOutput>(config, {
    method: 'POST',
    path: `/v1/keys/${encodeURIComponent(id)}/revoke`,
    body: {},
  });
}

